define(["core/modal"],function(Modal){"use strict";var initialized=false,state=new WeakMap();function getStep(c){var card=c.querySelector(".carrousel-card-item");if(!card)return 216;var gap=parseFloat(window.getComputedStyle(c).gap)||16;return card.offsetWidth+gap;}function getVisibleCount(c){var card=c.querySelector(".carrousel-card-item");if(!card)return 3;var step=card.offsetWidth+(parseFloat(window.getComputedStyle(c).gap)||16);var w=c.closest(".carrousel-nav-wrapper").clientWidth;return Math.max(1,Math.floor(w/step));}function getTotalCards(c){return c.querySelectorAll(".carrousel-card-item").length;}function applyTransform(c,idx){c.style.transform="translateX(-"+(idx*getStep(c))+"px)";}function showSubcourseModal(contentEl){var titleEl=contentEl.querySelector(".carrousel-modal-title");var bodyEl=contentEl.querySelector(".carrousel-modal-body");var courseUrl=contentEl.getAttribute("data-courseurl");var gotoText=contentEl.getAttribute("data-gototext");if(!titleEl||!bodyEl)return;var footer=courseUrl?'<a href="'+courseUrl+'" class="btn btn-primary">'+gotoText+'</a>':"";Modal.create({title:titleEl.innerHTML,body:bodyEl.innerHTML,footer:footer,isVerticallyCentered:true,scrollable:true,removeOnClose:true}).then(function(modal){modal.show();return modal;});}function init(){if(initialized)return;initialized=true;document.addEventListener("click",function(e){var btn=e.target.closest(".carrousel-prev-btn,.carrousel-next-btn");if(btn){var wrapper=btn.closest(".carrousel-nav-wrapper");if(!wrapper)return;var container=wrapper.querySelector(".carrousel-scroll-container");if(!container)return;if(!state.has(wrapper))state.set(wrapper,{index:0});var s=state.get(wrapper);var max=Math.max(0,getTotalCards(container)-getVisibleCount(container));if(btn.classList.contains("carrousel-prev-btn")){s.index=Math.max(0,s.index-1);}else{s.index=Math.min(max,s.index+1);}applyTransform(container,s.index);return;}var infoBtn=e.target.closest(".carrousel-subcourse-info-btn");if(infoBtn){var modalId=infoBtn.getAttribute("data-modal");var contentEl=modalId?document.getElementById(modalId):null;if(contentEl)showSubcourseModal(contentEl);}});}return{init:init};});
